Q: How to calculate integer logarithm of base 3, using fast bit operations? A: <p>Yes, using the same method as <a href="https://graphics.stanford.edu/%7Eseander/bithacks.html#IntegerLog10" rel="nofollow noreferrer">Find integer log base 10 of an integer</a> we can achieve the same thing. We just need to replace powers of 10 with powers of 3, log<sub>10</sub>2 with log<sub>3</sub>2, and a multiplication of <sup>1</sup>⁄<sub>log<sub>3</sub>2</sub> ≈ ³²³⁄₅₁₂ is used</p>
<p>Here's a simple PoC in JavaScript that you can try live in the browser. See the function <code>ilog3()</code></p>
<p><div class="snippet" data-lang="js" data-hide="false" data-console="true" data-babel="false" data-babel-preset-react="false" data-babel-preset-ts="false">
<div class="snippet-code">
<pre class="snippet-code-js lang-js prettyprint-override"><code>const POW3 = new Int32Array([ 1, 3, 9, 27, 81, 243, 729,
  2187, 6561, 19683, 59049, 177147, 531441, 1594323, 4782969,
  14348907, 43046721, 129140163, 387420489, 1162261467 ])

function ilog2(x) {
  // Get the position of the most significant bit by calling the built-in
  // find-first-set/count-leading-zero/integer-log-2/whatever method
  return 31 - Math.clz32(x);

  // In languages that don't have such integer log2 method when we can
  // approximate using floating-point math, but it's much slower
  // return Math.trunc(Math.log2(x))
}

function ilog3(x) {
  let t = (ilog2(x) + 1)*323 &gt;&gt;&gt; 9
  return t - (x &lt; POW3[t])
}

allOK = true
const Log3 = Math.log(3)
function check(x) {
  a = ilog3(x);
  b = Math.trunc(Math.log(x)/Log3);
  if (a != b) {
    console.log([x, a, b])
    allOK = false
  }
}

function checkAll(x) {
  if (x &gt; 2) { check(x - 2) }
  if (x &gt; 1) { check(x - 1) }
  check(x)
  check(x + 1)
  check(x + 2)
}

// Check if log3 around powers of 3 are correct
POW3.forEach(checkAll)
if (allOK) { console.log("OK") }</code></pre>
